def _coordinates(study, x):
    from scipy.special import erf
    from scipy.optimize import least_squares
    a = study['panel_a']
    (A, v) = (_design(a['u']), a['v'])
    keep = np.ones(len(A), dtype=bool)
    for _ in range(6):
        w = _fit(A[keep], v[keep])
        e = np.linalg.norm(A @ w - v, axis=1)
        good = e < max(0.001, 3 * np.median(e))
        if np.array_equal(keep, good) or good.sum() < A.shape[1]:
            break
        keep = good
    z = np.linalg.solve(w[1:].T, (x - w[0]).T).T
    p = study['panel_b']
    (u, v) = (p['u'], p['v'])

    def phi(q, u):
        return _design(erf(q[0] * u) + q[1] * u)

    def residual(q):
        F = phi(q, u)
        return (F @ _fit(F, v) - v).ravel()
    sols = [least_squares(residual, [a, -0.5 * a], bounds=([0.1, -8], [4, 8]), max_nfev=80) for a in [0.4, 0.8, 1.4, 2.2]]
    q = min(sols, key=lambda o: o.cost).x
    b = phi(q, z) @ _fit(phi(q, u), v)
    return (z, b)

def basis(u, kind):
    z = af(u)
    q = np.column_stack([u[:, i] * u[:, j] for i in range(4) for j in range(i, 4)])
    if kind == 'lin':
        return z
    if kind == 'diag':
        return np.c_[z, u * u]
    if kind == 'quad':
        return np.c_[z, q]
    if kind == 'odd':
        return np.c_[z, u ** 3]
    if kind == 'trig':
        return np.c_[z, np.sin(u), np.cos(u)]
    if kind == 'tanh':
        return np.c_[z, np.tanh(u), np.tanh(u) ** 2]
    if kind == 'cross':
        return np.c_[z, q[:, [1, 2, 3, 5, 6, 8]]]
